python3 - << 'PYEOF' > /tmp/new_flow.json
import json

# Load existing flow
with open('/work/output/artifacts/skill-flow-ipe-ceql-where/CeqlWhereTest/CeqlWhereTest/CeqlWhereTest.flow') as f:
    flow = json.load(f)

# Load OOTB definitions (just the Node object from Data.Node)
def load_def(path):
    with open(path) as f:
        return json.load(f)['Data']['Node']

def_end = load_def('/tmp/def_end.json')
def_terminate = load_def('/tmp/def_terminate.json')
def_script = load_def('/tmp/def_script.json')

# 1. Update listEntraGroups1 to enable error handling
for node in flow['nodes']:
    if node['id'] == 'listEntraGroups1':
        node['inputs']['errorHandlingEnabled'] = True

# 2. Add new user-owned nodes
flow['nodes'].extend([
    {
        "id": "logSuccess",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Log passed"},
        "inputs": {
            "script": "return { message: \"CeqlWhere test passed\" };"
        }
    },
    {
        "id": "endSuccess",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": {"label": "Done"},
        "inputs": {}
    },
    {
        "id": "terminate1",
        "type": "core.logic.terminate",
        "typeVersion": "1.0",
        "display": {"label": "CeqlWhere test failed"},
        "inputs": {}
    }
])

# 3. Add new definitions
flow['definitions'].extend([def_script, def_end, def_terminate])

# 4. Add edges
flow['edges'] = [
    {
        "id": "e_start_list",
        "sourceNodeId": "start",
        "sourcePortId": "output",
        "targetNodeId": "listEntraGroups1",
        "targetPort": "input"
    },
    {
        "id": "e_list_logSuccess",
        "sourceNodeId": "listEntraGroups1",
        "sourcePortId": "output",
        "targetNodeId": "logSuccess",
        "targetPort": "input"
    },
    {
        "id": "e_list_terminate",
        "sourceNodeId": "listEntraGroups1",
        "sourcePortId": "error",
        "targetNodeId": "terminate1",
        "targetPort": "input"
    },
    {
        "id": "e_logSuccess_end",
        "sourceNodeId": "logSuccess",
        "sourcePortId": "success",
        "targetNodeId": "endSuccess",
        "targetPort": "input"
    }
]

# 5. Add layout placeholder entries for new nodes (format will overwrite positions/sizes)
for nid in ["logSuccess", "endSuccess", "terminate1"]:
    flow['layout']['nodes'][nid] = {
        "position": {"x": 0, "y": 0},
        "size": {"width": 96, "height": 96},
        "collapsed": False
    }

print(json.dumps(flow, indent=2))
PYEOF
echo "BUILD_OK: $(wc -l /tmp/new_flow.json)"

